Mode Deskribapena <code>PDO::FETCH_ASSOC</code> Array asoziatiboa, <code>$fila['nombre']</code> <code>PDO::FETCH_NUM</code> Array numerikoa, <code>$fila[0]</code> <code>PDO::FETCH_BOTH</code> Biak, <code>$fila[0]</code> edo <code>$fila['id']</code> <code>PDO::FETCH_OBJ</code> Objektua, <code>$fila-&gt;nombre</code> <code>PDO::FETCH_CLASS</code> Zure klasea, <code>$persona-&gt;edad</code> <code>PDO::FETCH_COLUMN</code> Zutabe bakarra, <code>["Jon", "Ane"]</code> <code>PDO::FETCH_KEY_PAIR</code> Gako → Balio, <code>[1 =&gt; "Jon"]</code> <code>PDO::FETCH_GROUP</code> Gako → Array multzoa <code>PDO::FETCH_UNIQUE</code> Gako bakarrak <pre><code>    // FETCH_ASSOC - Emaitzak array asoziatibo moduan itzultzen ditu (gakoak zutabeen izenak dira).
    // Gehien erabiltzen dena da, oso garbia baita.

    $stmt = $pdo-&gt;query("SELECT id, nombre, edad FROM personas");
    while ($fila = $stmt-&gt;fetch(PDO::FETCH_ASSOC)) {
        echo $fila['id'] . " - " . $fila['nombre'] . " (" . $fila['edad'] . ")&lt;br&gt;";
    }

    // Emaitza:
    // 1 - Jon (25)
    // 2 - Ane (30)

    // FETCH_NUM - Emaitzak array numeriko moduan itzultzen ditu (gakoak zenbakiak dira).

    $stmt = $pdo-&gt;query("SELECT id, nombre, edad FROM personas");
    while ($fila = $stmt-&gt;fetch(PDO::FETCH_NUM)) {
        echo $fila[0] . " - " . $fila[1] . " (" . $fila[2] . ")&lt;br&gt;";
    }

    // Emaitza:
    // 1 - Jon (25)
    // 2 - Ane (30)

    // FETCH_BOTH - Emaitzak biak batera itzultzen ditu: gako numerikoekin eta asoziatiboekin.
    // Hau da, $fila[0] eta $fila['id'] berdinak izango dira.
    // Normalean ez da oso gomendagarria, memoria gehiago erabiltzen duelako.

    $stmt = $pdo-&gt;query("SELECT id, nombre FROM personas");
    $fila = $stmt-&gt;fetch(PDO::FETCH_BOTH);
    echo $fila[0];       // id
    echo $fila['nombre']; // nombre


    // FETCH_OBJ - Emaitzak objektu moduan itzultzen ditu (gakoak objektuaren atributuak dira).

    $stmt = $pdo-&gt;query("SELECT nombre, edad FROM personas");
    while ($fila = $stmt-&gt;fetch(PDO::FETCH_OBJ)) {
        echo $fila-&gt;nombre . " (" . $fila-&gt;edad . ")&lt;br&gt;";
    }

    // Emaitza:
    // Jon (25)
    // Ane (30)
</code></pre>
